import { Injectable, Controller, Get, Inject } from '@nestjs/common';

/**
 * Result of authenticating against the Vault-style secret store.
 * `leaseDurationSeconds` tells the caller how long the returned token/lease
 * is valid for before it must be renewed.
 */
interface SecretStoreLoginResult {
  token: string;
  leaseDurationSeconds: number;
}

/**
 * Thin client wrapping calls to the external secret store (e.g. HashiCorp Vault).
 */
@Injectable()
export class SecretStoreClient {
  /**
   * Authenticates against the secret store and returns a short-lived token
   * plus the lease duration for that token.
   */
  async login(): Promise<SecretStoreLoginResult> {
    // Network round trip #1: authenticate against the external store.
    const response = await fetch('https://secret-store.internal/v1/auth/login', {
      method: 'POST',
    });
    return response.json() as Promise<SecretStoreLoginResult>;
  }

  /**
   * Reads the secret value stored at `path`, authenticated with `token`.
   */
  async read(path: string, token: string): Promise<string> {
    // Network round trip #2: read the actual secret value.
    const response = await fetch(`https://secret-store.internal/v1/secret/${path}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const body = (await response.json()) as { value: string };
    return body.value;
  }
}

/**
 * Provides the third-party API signing secret to the rest of the app.
 */
@Injectable()
export class SecretsService {
  constructor(private readonly client: SecretStoreClient) {}

  /**
   * Fetches the outbound-signing secret. Currently re-authenticates and
   * re-reads from the secret store on every single call.
   */
  async getApiKey(): Promise<string> {
    // Every call logs in fresh — leaseDurationSeconds is read off the
    // response but never stored or acted upon anywhere.
    const { token, leaseDurationSeconds } = await this.client.login();

    // Every call reads the secret value fresh too.
    const secret = await this.client.read('third-party/api-signing-key', token);

    return secret;
  }
}

/**
 * Handles outbound requests to a third-party API that must be signed
 * with the secret above.
 */
@Controller('payments')
export class PaymentsController {
  constructor(private readonly secretsService: SecretsService) {}

  @Get('charge')
  async charge(): Promise<{ status: string }> {
    // getApiKey() is invoked on the request path of every single call,
    // paying the full login+read round trip each time.
    const apiKey = await this.secretsService.getApiKey();

    await fetch('https://third-party-payments.example.com/charge', {
      method: 'POST',
      headers: { 'X-Api-Key': apiKey },
    });

    return { status: 'ok' };
  }
}
